def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n == 1:
        return 'D'

    mine = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = sum(1 for a in opp if a == 'C')
    total_coop = opp_c / float(n)

    w = min(10, n)
    recent_opp = opp[n - w:]
    recent_coop = sum(1 for a in recent_opp if a == 'C') / float(w)

    w2 = min(20, n)
    recent20_opp = opp[n - w2:]
    recent20_coop = sum(1 for a in recent20_opp if a == 'C') / float(w2)

    afterC_c = 0
    afterC_d = 0
    afterD_c = 0
    afterD_d = 0
    recentD_c = 0
    recentD_d = 0
    recent_start = max(0, n - 15)

    # Count how the opponent responds when we defect in a non-mutual round.
    # Mutual (D,D) rounds are ignored as evidence of unilateral forgiveness,
    # which also keeps self-play from turning into a mutual-defection trap.
    for i in range(n - 1):
        if mine[i] == 'C':
            if opp[i + 1] == 'C':
                afterC_c += 1
            else:
                afterC_d += 1
        elif opp[i] == 'C':
            if opp[i + 1] == 'C':
                afterD_c += 1
                if i >= recent_start:
                    recentD_c += 1
            else:
                afterD_d += 1
                if i >= recent_start:
                    recentD_d += 1

    opp_run = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            opp_run += 1
        else:
            break

    last_mine = mine[-1]
    last_opp = opp[-1]
    prev_mine = mine[-2]

    # Against clearly hostile opponents, defend.
    if opp_c == 0:
        return 'D'
    if n >= 5 and total_coop < 0.2:
        return 'D'
    if recent_coop <= 0.2:
        return 'D'
    if recent20_coop <= 0.25 and total_coop < 0.45:
        return 'D'

    if last_opp == 'D':
        # Persistent hostility is treated as hostile.
        if opp_run >= 3:
            return 'D'
        if opp_run >= 2 and recent_coop <= 0.45:
            return 'D'

        # If both just defected, try to break a symmetric or retaliatory cycle.
        if last_mine == 'D' and total_coop >= 0.5 and recent_coop >= 0.45:
            return 'C'

        # One provoked punishment after our recent D should not become a feud.
        if opp_run == 1 and prev_mine == 'D':
            return 'C'

        # Unprovoked or ongoing defection: punish.
        return 'D'

    # If we just defected and have not yet observed the response, confirm.
    if last_mine == 'D' and afterD_c + afterD_d == 0:
        return 'C'

    # If the opponent usually keeps cooperating after our unilateral defects,
    # exploit that forgiving behavior.
    if recentD_d == 0:
        if recentD_c >= 2 and total_coop > 0.5 and recent_coop > 0.5:
            if not (n > 95 and recentD_c < 3):
                return 'D'

        # Early evidence: one clean forgiveness is promising but not certain.
        if recentD_c == 1 and total_coop > 0.6 and recent_coop > 0.6:
            if rng.random() < 0.75:
                return 'D'
    else:
        # Opponent does retaliate sometimes.  Only defect if recent evidence
        # says forgiveness is still much more likely than punishment.
        if recentD_c >= 3 * recentD_d and recentD_d <= 2:
            if total_coop > 0.65 and recent_coop > 0.55:
                p = 0.55 + 0.10 * recentD_c - 0.15 * recentD_d
                if n > 90:
                    p -= 0.30
                if recent_coop < 0.80:
                    p -= 0.20
                if p > 0.0 and rng.random() < p:
                    return 'D'

    # Occasional exploration after a long clean cooperative period, but only
    # when the history is not fully symmetric; this avoids repeated mutual
    # self-defection loops while still detecting forgiving opponents later.
    if (
        recentD_c + recentD_d == 0
        and total_coop > 0.85
        and recent_coop > 0.75
        and n > 30
    ):
        symmetric = True
        for i in range(n):
            if mine[i] != opp[i]:
                symmetric = False
                break
        if not symmetric and n % 23 == 0 and rng.random() < 0.35:
            return 'D'

    # If opponent behavior seems insensitive to our action, defecting is
    # usually the better response, especially near the finite end.
    if n >= 6:
        afterC_total = afterC_c + afterC_d
        afterD_total = afterD_c + afterD_d

        if afterC_total > 0:
            pCC = (afterC_c + 0.8) / (afterC_total + 1.6)
        else:
            pCC = 0.85

        if afterD_total > 0:
            pCD = (afterD_c + 0.8) / (afterD_total + 1.6)
        else:
            pCD = 0.2

        sensitivity = pCC - pCD
        p_now = pCC if last_mine == 'C' else pCD
        remaining = 100 - n
        weight = 1.0 + remaining / 15.0

        if sensitivity < 0.35 and sensitivity < (1.0 + p_now) / (4.0 * weight):
            return 'D'

    return 'C'
